const body = $input.first().json.body || {};
const rawMetrics = body.metrics || {};
const values = [];
const ts = new Date().toISOString();
if (typeof rawMetrics === 'object' && rawMetrics !== null) {
  for (const [nameRaw, data] of Object.entries(rawMetrics)) {
    const name = nameRaw.replace(/'/g, '');
    if (!name || name === 'unknown') continue;
    values.push(`('${name}', 'cpu', ${parseFloat(data.cpu || 0).toFixed(4)}, '${ts}')`);
    values.push(`('${name}', 'memory', ${parseFloat(data.memory || 0).toFixed(4)}, '${ts}')`);
  }
}
if (values.length === 0) return [{ json: { query: 'SELECT 1;', count: 0 } }];
return [{ json: { query: 'INSERT INTO tlab_events (container, metric_type, metric_value, recorded_at) VALUES ' + values.join(','), count: values.length / 2 } }];

const rows = $input.all();
if (!rows.length) return [{ json: { history: 'No actions found in the last 24 hours' } }];
const text = rows.map(r => { const d = r.json; const time = d.decided_at ? new Date(d.decided_at).toLocaleString() : 'pending'; return `- ${d.action} ${d.target}: ${d.decision||'pending'} / ${d.result||'?'} at ${time}`; }).join('\n');
return [{ json: { history: text } }];

const rows = $input.all();
if (!rows.length) return [{ json: { memory: 'No lessons recorded yet' } }];
const text = rows.map(r => { const d = r.json; return `- ${d.container} [${d.issue_type}]: ${d.root_cause||'Issue'} → Solution: ${d.solution} (${d.outcome}, confidence: ${d.confidence})`; }).join('\n');
return [{ json: { memory: text } }];
